-- Migration: Year 2 - Systemic Microbiology MCQ Bank (PART 1: 1-70)
-- Date: 2026-04-25
-- Based on: Clinical Microbiology Made Ridiculously Simple, Levinson, and Parham

BEGIN;

DO $$ 
DECLARE 
    v_topic_id UUID;
BEGIN
    -- 1. Create/Ensure Topic "Systemic Microbiology" for Year 2
    INSERT INTO topics (title, slug, semester_id, year_id, "order", usmle_step)
    VALUES ('Systemic Microbiology', 'systemic-microbiology', 3, 2, 35, NULL)
    ON CONFLICT (slug) DO UPDATE SET 
        title = EXCLUDED.title,
        year_id = 2, 
        semester_id = 3, 
        usmle_step = NULL,
        "order" = 35
    RETURNING id INTO v_topic_id;

    -- 2. Master Wipe: Clear existing questions to remove redundancy (the 453 questions)
    DELETE FROM mcqs WHERE topic_id = v_topic_id;

    -- 2. Prevent Duplicates by removing existing questions for this part
    DELETE FROM mcqs 
    WHERE topic_id = v_topic_id 
    AND question IN (
        'A 19-year-old female presents with high fever, a diffuse erythematous rash resembling a sunburn, and sudden hypotension during her menses. Blood cultures are negative, but a vaginal swab grows Gram-positive cocci in clusters. What is the mechanism of the toxin involved?',
        'A patient develops severe back pain and fever 3 weeks after a dental procedure. MRI shows vertebral osteomyelitis. The isolated organism is alpha-hemolytic, optochin-resistant, and fails to grow in 6.5% NaCl. Which of the following is a key virulence factor for this organism?',
        'A 70-year-old man with a history of colonic polyps is diagnosed with endocarditis caused by Streptococcus gallolyticus (formerly S. bovis). What is the most appropriate next step in management?',
        'A child presents with a "honey-crusted" skin lesion on his face. Gram stain shows Gram-positive cocci in chains. The patient is treated, but two weeks later develops periorbital edema and cola-colored urine. Which of the following is TRUE regarding this condition?',
        'A patient presents with a well-demarcated, raised, bright red skin infection on the face (Erysipelas). Which organism is the most common cause?',
        'Which component of the Streptococcus pneumoniae cell wall is the primary target of the current conjugated vaccine?',
        'A patient with a history of rheumatic heart disease undergoes a valve replacement. He later develops endocarditis. The organism is catalase-negative, gamma-hemolytic, and grows in 6.5% NaCl. What is the most likely organism?',
        'A 25-year-old male presents with a high fever, severe headache, and neck stiffness. CSF shows high neutrophils, low glucose, and Gram-positive lancet-shaped diplococci. What is the primary virulence factor that prevents phagocytosis?',
        'A 65-year-old female with a history of recurrent UTIs develops a fever and flank pain. Urine culture shows Gram-positive cocci in pairs and chains that are catalase-negative and bile-esculin positive. Diagnosis?',
        'What is the mechanism of the "M protein" of Streptococcus pyogenes?',
        'A patient with a deep puncture wound develops severe muscle spasms and "lockjaw." The causative organism is a Gram-positive, spore-forming anaerobic rod. What is the mechanism of its toxin?',
        'Which organism is a Gram-positive rod that shows "Chinese-letter" morphology and produces a toxin that ADP-ribosylates EF-2?',
        'A pregnant woman develops a mild febrile illness after eating unpasteurized brie cheese. She is at risk for neonatal meningitis. The organism shows "tumbling motility" at room temperature and "actin rockets" inside host cells. It is:',
        'A patient with a history of diabetes develops a painful, crepitant (gas-forming) infection in his thigh after a trauma. The organism is a large Gram-positive anaerobic rod. It is:',
        'A patient presents with a painless, black eschar on his forearm after handling sheep wool. The organism is a large, square-ended Gram-positive rod in chains with a polypeptide capsule. It is:',
        'A patient presents with a "woody" hard swelling at the angle of the jaw with multiple draining sinuses showing "sulfur granules." The organism is a branching Gram-positive anaerobic rod. It is:',
        'A patient with a history of dental work has a lung abscess. Gram stain shows branching Gram-positive rods that are partially acid-fast. Diagnosis?',
        'Which toxin is responsible for the "scalded skin syndrome" seen in neonates?',
        'A 30-year-old patient presents with a fever and a new heart murmur. He is an IV drug user. Blood cultures grow S. aureus. Which valve is most likely involved?',
        'What is the mechanism of action of the Panton-Valentine Leukocidin (PVL) toxin produced by some MRSA strains?',
        'Which Gram-positive rod is associated with "food poisoning" from reheated rice, causing nausea and vomiting within hours?',
        'A patient with a history of cystic fibrosis presents with a pulmonary infection. The organism is a Gram-negative rod, oxidase positive, and produces a blue-green pigment. It is:',
        'What is the mechanism of the Exotoxin A produced by Pseudomonas aeruginosa?',
        'Which Gram-negative rod is the most common cause of UTIs and shows "green metallic sheen" on EMB agar?',
        'A child presents with bloody diarrhea and later develops Hemolytic Uremic Syndrome (HUS). The organism is E. coli O157:H7. What is the mechanism of its toxin?',
        'A patient with a history of a recent UTI develops a kidney stone. The urine is alkaline (pH 8.5), and the organism is a Gram-negative rod that shows "swarming motility" on agar. It is:',
        'A patient returning from a trip to South Asia presents with profound, "rice-water" diarrhea and severe dehydration. The organism is a comma-shaped Gram-negative rod. It is:',
        'What is the mechanism of the Cholera toxin?',
        'A patient presents with high fever, a "rose spot" rash on the abdomen, and bradycardia. He recently traveled to Mexico. Blood cultures grow a Gram-negative rod. Diagnosis?',
        'A patient presents with bloody diarrhea and tenesmus. Stool culture shows a Gram-negative rod that is non-motile and does not ferment lactose. What is the mechanism of its toxin?',
        'A patient with an "atypical" pneumonia also has diarrhea and hyponatremia. He is a smoker. The organism requires buffered charcoal yeast extract (BCYE) agar. It is:',
        'A 5-year-old child presents with a "barking" cough and inspiratory stridor. This is likely Croup. Which virus is the most common cause?',
        'A child with a history of a "slapped-cheek" rash now has an aplastic crisis. He has sickle cell disease. Which virus is responsible?',
        'A patient presents with painful, umbilicated flesh-colored papules on the trunk. Biopsy shows Guarnieri bodies. Diagnosis?',
        'A patient presents with a high fever, headache, and a petechial rash. He is a college student living in a dormitory. CSF shows Gram-negative diplococci. What is the primary virulence factor?',
        'Which organism is a small Gram-negative "coccobacillus" that requires factors X (hemin) and V (NAD) for growth?',
        'A patient presents with a painful genital ulcer and painful inguinal lymphadenopathy (buboes). Gram stain shows Gram-negative coccobacilli in a "school of fish" pattern. Diagnosis?',
        'A patient presents with a persistent cough for 4 weeks that comes in violent paroxysms followed by a loud inspiratory "whoop." What is the mechanism of the toxin?',
        'A patient presents with a fever and a localized painful lymphadenopathy after being scratched by a cat. The organism is:',
        'A patient presents with fever and weight loss after returning from a trip to the Mediterranean where he consumed unpasteurized goat cheese. The organism is a Gram-negative coccobacillus. Diagnosis?',
        'A patient presents with a high fever and a painful, swollen lymph node (bubo) in the groin after being bitten by a flea in the Southwestern US. Diagnosis?',
        'What is the primary reservoir for Francisella tularensis (Tularemia)?',
        'Which organism is a Gram-negative rod associated with "currant jelly" sputum in alcoholics?',
        'A patient has a "Montezuma''s Revenge" (Traveler''s diarrhea). Which toxin is responsible for the watery diarrhea?',
        'Which organism is a Gram-negative rod that causes "Donovan bodies" (intracellular inclusions) in a painless genital ulcer?',
        'Which Mycobacterium species is associated with "fish tank granuloma"?',
        'Which component of the Mycobacterium tuberculosis cell wall is responsible for its "acid-fast" staining property?',
        'What is the function of the "Cord Factor" in Mycobacterium tuberculosis?',
        'A patient with AIDS has a CD4 count of 40 and presents with fever, weight loss, and anemia. Blood cultures are positive for acid-fast bacilli. What is the most likely organism?',
        'A patient from Southeast Asia presents with hypopigmented skin patches on his arms that are anesthetic (lack sensation). He has thickened ulnar nerves. He has a strong Th1 response and positive lepromin skin test. Which form of leprosy is this?',
        'In the lepromatous form of leprosy, the patient has a weak Th1 response and a predominant Th2 response. This leads to:',
        'What is the drug of choice for treating Nocardia infections?',
        'A 40-year-old male presents with chronic cough, night sweats, and weight loss. CXR shows a cavitary lesion in the right upper lobe. What is the primary mediator of the caseous necrosis seen in his granulomas?',
        'Which Mycobacterium species causes a "fish tank granuloma" after a skin abrasion in a swimming pool or aquarium?',
        'Which organism is the most common cause of "Atypical" (walking) pneumonia in young adults and lacks a cell wall?',
        'What is the diagnostic test for Mycoplasma pneumoniae?',
        'A patient presents with a "painless" penile ulcer (chancre). Dark-field microscopy shows spirochetes. Diagnosis?',
        'Which stage of Syphilis is characterized by a maculopapular rash on the palms and soles and condyloma lata?',
        'A patient with Tertiary Syphilis presents with a "lightning-like" pain in the legs and a wide-based gait. Diagnosis?',
        'What is the "Argyll Robertson pupil"?',
        'A patient presents with a "bullseye" rash (Erythema migrans) after a hiking trip in Connecticut. Diagnosis?',
        'What is the vector for Lyme disease?',
        'A patient presents with a high fever, headache, and a rash that starts on the wrists and ankles and spreads to the trunk. He was recently hiking in North Carolina. Diagnosis?',
        'What is the vector for Rocky Mountain Spotted Fever?',
        'A patient presents with a high fever and headache after exposure to a parturient cow (giving birth). He has no rash. Diagnosis?',
        'A patient presents with jaundice, fever, and kidney dysfunction after swimming in a lake contaminated with animal urine. The organism is a spirochete with "hooked ends." Diagnosis?',
        'Which organism causes "Epidemic Typhus" and is transmitted by the human body louse?',
        'Which organism causes "Endemic Typhus" and is transmitted by fleas?',
        'Which organism is an obligate intracellular bacterium that causes "Trachoma" (leading cause of blindness) and "NGU"?',
        'What are the "Elementary Body" (EB) and "Reticulate Body" (RB) in the Chlamydia life cycle?'
    );

    -- SECTION 1: GRAM-POSITIVE COCCI (1-15)
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 19-year-old female presents with high fever, a diffuse erythematous rash resembling a sunburn, and sudden hypotension during her menses. Blood cultures are negative, but a vaginal swab grows Gram-positive cocci in clusters. What is the mechanism of the toxin involved?', '["ADP-ribosylation of EF-2", "Binding to MHC II and T-cell receptor beta-chain", "Cleavage of desmoglein-1", "Inhibition of glycine release"]', 1, 'TSST-1 from S. aureus is a superantigen that cross-links the beta-chain of the T-cell receptor to MHC II on APCs, causing a massive cytokine storm (IFN-gamma, IL-2).'),
    (v_topic_id, 'A patient develops severe back pain and fever 3 weeks after a dental procedure. MRI shows vertebral osteomyelitis. The isolated organism is alpha-hemolytic, optochin-resistant, and fails to grow in 6.5% NaCl. Which of the following is a key virulence factor for this organism?', '["Protein A", "Dextran production from sucrose", "M protein", "IgA protease"]', 1, 'Viridans group streptococci (like S. mutans/sanguinis) produce dextrans that allow them to adhere to fibrin-platelet aggregates on damaged heart valves or bone surfaces.'),
    (v_topic_id, 'A 70-year-old man with a history of colonic polyps is diagnosed with endocarditis caused by Streptococcus gallolyticus (formerly S. bovis). What is the most appropriate next step in management?', '["Transesophageal echocardiogram only", "Colonoscopy", "Long-term prophylactic penicillin", "Repeat blood cultures in 24 hours"]', 1, 'S. bovis (Group D) bacteremia/endocarditis has a strong clinical association with colonic malignancy or polyps.'),
    (v_topic_id, 'Which component of the Streptococcus pyogenes cell wall is responsible for preventing phagocytosis by interfering with the alternative complement pathway?', '["Lipoteichoic acid", "M protein", "Hyaluronic acid capsule", "Streptolysin O"]', 1, 'M protein is the major virulence factor; it inhibits complement activation and opsonization. Hyaluronic acid also helps (by mimicking host tissue), but M protein specifically targets complement.'),
    (v_topic_id, 'A 5-year-old boy presents with periorbital edema and dark-colored urine 2 weeks after recovering from a "honey-crusted" skin infection. Which of the following is TRUE regarding his condition?', '["It could have been prevented by early antibiotic treatment of the skin infection", "It is caused by Type III hypersensitivity (immune complex deposition)", "He is likely to develop Rheumatic Fever next", "The causal organism is Catalase positive"]', 1, 'Post-streptococcal glomerulonephritis (PSGN) follows both pharyngeal and skin infections and is NOT prevented by antibiotics (unlike Rheumatic Fever). It is a Type III hypersensitivity reaction.'),
    (v_topic_id, 'A patient in the ICU with a central venous catheter develops bacteremia with a Gram-positive coccus that is catalase-positive and coagulase-negative. The organism is resistant to nafcillin. What is the mechanism of this resistance?', '["Production of beta-lactamase", "Alteration of penicillin-binding proteins (PBP2a)", "Efflux pump activation", "Mutation in DNA gyrase"]', 1, 'Methicillin resistance (MRSA/MRSE) is due to the mecA gene, which encodes an altered PBP (PBP2a) with low affinity for beta-lactams.'),
    (v_topic_id, 'A 24-year-old female presents with frequent, painful urination. Urine culture grows Gram-positive cocci in clusters that are catalase-positive, coagulase-negative, and resistant to novobiocin. This organism is most likely:', '["Staphylococcus epidermidis", "Staphylococcus saprophyticus", "Enterococcus faecalis", "Streptococcus agalactiae"]', 1, 'S. saprophyticus is the second most common cause of UTIs in young, sexually active females (E. coli is #1). It is distinguished from S. epidermidis by novobiocin resistance.'),
    (v_topic_id, 'An infant born to a mother who received no prenatal care develops respiratory distress and sepsis 12 hours after birth. Gram stain of the CSF shows Gram-positive cocci in chains. The organism shows a widened zone of hemolysis when streaked near Staphylococcus aureus. What is this phenomenon called?', '["Quellung reaction", "CAMP test", "Nagler reaction", "Elek test"]', 1, 'The CAMP test identifies Group B Strep (S. agalactiae), which produces CAMP factor that enhances the beta-hemolysis of S. aureus.'),
    (v_topic_id, 'A patient with an intra-abdominal abscess develops endocarditis. The organism is a Gram-positive coccus that grows in 6.5% NaCl and hydrolyzes esculin in the presence of bile. It is resistant to vancomycin. What is the molecular basis for this resistance?', '["Replacement of D-Ala-D-Ala with D-Ala-D-Lac", "Methylation of the 23S rRNA", "Acetylation of the antibiotic", "Active efflux of the drug"]', 0, 'Vancomycin-resistant Enterococci (VRE) change the peptidoglycan precursor terminal from D-Ala-D-Ala to D-Ala-D-Lactate, preventing vancomycin binding.'),
    (v_topic_id, 'Which Streptococcus pneumoniae virulence factor is specifically responsible for cleaving secretory antibodies on mucosal surfaces?', '["Pneumolysin", "Capsule", "IgA protease", "Autolysin"]', 2, 'IgA protease allows S. pneumoniae, H. influenzae, and Neisseria to colonize the respiratory and genital mucosa.'),
    (v_topic_id, 'A 30-year-old male with HIV presents with a painful, erythematous area on his right thigh with "sharp, well-demarcated borders." He has a high fever. What is the most likely causative agent?', '["Staphylococcus aureus", "Streptococcus pyogenes", "Clostridium perfringens", "Pseudomonas aeruginosa"]', 1, 'Erysipelas is a superficial cellulitis with well-defined borders, almost always caused by S. pyogenes (GAS).'),
    (v_topic_id, 'Which toxin of Staphylococcus aureus is responsible for "Scalded Skin Syndrome" by cleaving desmoglein-1 in the stratum granulosum?', '["Alpha-toxin", "Exfoliative toxin", "Enterotoxin B", "Panton-Valentine Leukocidid"]', 1, 'Exfoliative toxins (A and B) act as proteases targeting desmosomes, leading to skin sloughing.'),
    (v_topic_id, 'A patient presents with a severe sore throat. A rapid strep test is positive. If left untreated, which complication is mediated by "molecular mimicry" between bacterial M protein and host cardiac myosin?', '["Post-streptococcal glomerulonephritis", "Acute Rheumatic Fever", "Scarlet Fever", "Toxic Shock Syndrome"]', 1, 'Rheumatic Fever is a Type II hypersensitivity where antibodies against M protein cross-react with heart tissue.'),
    (v_topic_id, 'Enterococcus species are naturally resistant to which class of antibiotics because they lack the necessary oxidative transport mechanism?', '["Beta-lactams", "Aminoglycosides", "Fluoroquinolones", "Tetracyclines"]', 1, 'Aminoglycosides require oxygen-dependent transport into the cell; Enterococci are anaerobic/aerotolerant and require a cell-wall active agent (like Penicillin) to facilitate aminoglycoside entry (synergy).'),
    (v_topic_id, 'What is the most common cause of prosthetic valve endocarditis within 60 days of surgery?', '["Staphylococcus aureus", "Staphylococcus epidermidis", "Streptococcus sanguinis", "Candida albicans"]', 1, 'S. epidermidis is the most common cause of early prosthetic valve endocarditis due to its ability to form biofilms on foreign material.');

    -- SECTION 2: GRAM-POSITIVE BACILLI (16-30)
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A worker in a wool-processing plant develops a painless skin ulcer with a black eschar and significant surrounding edema. The organism is a non-motile, Gram-positive rod with a polypeptide capsule. What are the two components of its primary toxin?', '["Lethal factor and Edema factor", "Toxin A and Toxin B", "Protective antigen and Lethal factor/Edema factor", "Alpha toxin and Theta toxin"]', 2, 'Bacillus anthracis toxin is tripartite: Protective Antigen (PA) mediates entry, while Lethal Factor (LF) and Edema Factor (EF) cause the pathology.'),
    (v_topic_id, 'What is the mechanism of the Edema Factor (EF) in Bacillus anthracis?', '["Inhibition of EF-2", "Adenylate cyclase that increases cAMP", "Zinc metalloproteinase that cleaves MAPKK", "Cleavage of SNARE proteins"]', 1, 'EF is a calmodulin-dependent adenylate cyclase. LF is the zinc metalloproteinase that cleaves MAPKK.'),
    (v_topic_id, 'A patient with a history of intravenous drug use presents with "drooping eyelids," double vision, and a "descending" symmetric paralysis. He is afebrile. What is the mechanism of the toxin responsible?', '["Blocks release of GABA and Glycine", "Blocks release of Acetylcholine at the neuromuscular junction", "ADP-ribosylation of G-protein", "Inhibition of protein synthesis"]', 1, 'Botulinum toxin cleaves SNARE proteins, preventing the release of excitatory acetylcholine, leading to flaccid paralysis.'),
    (v_topic_id, 'A 45-year-old male presents with "lockjaw" and a persistent grin (risus sardonicus) after stepping on a rusty nail. The toxin responsible travels via:', '["Anterograde axonal transport to the brain", "Retrograde axonal transport to the spinal cord", "Hematogenous spread to the kidneys", "Lymphatic spread to the lungs"]', 1, 'Tetanospasmin travels via retrograde axonal transport to the CNS, where it blocks inhibitory neurotransmitters (GABA/Glycine).'),
    (v_topic_id, 'A 35-year-old female presents with a gray, pseudomembranous pharyngitis. The causative agent appears as "Chinese-letter" arrangements on Gram stain. How does the toxin cause cell death?', '["Activation of adenylate cyclase", "ADP-ribosylation of Elongation Factor 2 (EF-2)", "Cleavage of 28S rRNA", "Disruption of the cell membrane"]', 1, 'Corynebacterium diphtheriae toxin inactivates EF-2, halting protein synthesis.'),
    (v_topic_id, 'Which organism is a Gram-positive, non-spore-forming rod that exhibits "tumbling motility" at 25°C and "actin rockets" for intracellular movement?', '["Bacillus cereus", "Listeria monocytogenes", "Erysipelothrix rhusiopathiae", "Corynebacterium diphtheriae"]', 1, 'Listeria is a facultative intracellular pathogen that uses host cell actin to move from cell to cell.'),
    (v_topic_id, 'A pregnant woman is advised to avoid unpasteurized cheeses to prevent infection with Listeria monocytogenes. What is the most common neonatal manifestation of this infection if acquired in utero?', '["Gas gangrene", "Granulomatosis infantiseptica", "Scaled skin syndrome", "Cystic fibrosis"]', 1, 'Early-onset Listeriosis in neonates presents as granulomatosis infantiseptica (disseminated abscesses/granulomas).'),
    (v_topic_id, 'A patient hospitalized for pneumonia develops profuse, watery diarrhea 5 days after starting Clindamycin. Stool assay detects Toxin A and Toxin B. What is the function of Toxin B?', '["Increases cAMP in intestinal cells", "Disrupts the actin cytoskeleton by rho-protein inhibition", "Inhibits protein synthesis", "Acts as a superantigen"]', 1, 'C. difficile Toxin A (enterotoxin) attracts neutrophils; Toxin B (cytotoxin) disrupts the cytoskeleton, causing cell death and pseudomembrane formation.'),
    (v_topic_id, 'A man develops a swollen, painful wound with "crepitus" (gas in the tissue) after a motorcycle accident. The Gram stain shows large Gram-positive rods. Which toxin is the primary virulence factor?', '["Tetanospasmin", "Lecithinase (Alpha-toxin)", "Verotoxin", "Toxin A"]', 1, 'Clostridium perfringens produces alpha-toxin (a lecithinase/phospholipase) that degrades cell membranes and causes myonecrosis.'),
    (v_topic_id, 'Bacillus cereus is associated with food poisoning from reheated rice. The emetic form is caused by:', '["A preformed heat-stable toxin", "Toxin production after ingestion (heat-labile)", "Invasion of the intestinal mucosa", "Endospore germination in the lungs"]', 0, 'The emetic (vomiting) type of B. cereus is caused by a cereulide toxin which is heat-stable and preformed in the food.'),
    (v_topic_id, 'Which Gram-positive rod is part of the normal vaginal flora and helps maintain an acidic pH by fermenting glycogen into lactic acid?', '["Gardnerella vaginalis", "Lactobacillus", "Staphylococcus epidermidis", "Actinomyces"]', 1, 'Lactobacilli maintain the vaginal pH around 4.5, which is protective against overgrowth of pathogens.'),
    (v_topic_id, 'A patient with a history of poor dental hygiene presents with a slow-growing, "woody" mass at the angle of the jaw that eventually drains through a sinus tract. The drainage contains yellow "sulfur granules." The organism is:', '["Nocardia asteroides", "Actinomyces israelii", "Mycobacterium kansasii", "Bacteroides fragilis"]', 1, 'Actinomyces israelii is an anaerobic Gram-positive branching rod that causes cervicofacial "lumpy jaw."'),
    (v_topic_id, 'An immunocompromised patient presents with a brain abscess and pulmonary nodules. Gram stain of the sputum shows branching Gram-positive rods that are partially acid-fast. The organism is:', '["Actinomyces israelii", "Nocardia asteroides", "Mycobacterium tuberculosis", "Aspergillus fumigatus"]', 1, 'Nocardia is aerobic, branching, and partially acid-fast (due to mycolic acids), unlike Actinomyces which is anaerobic and not acid-fast.'),
    (v_topic_id, 'How do humans typically acquire infection with Erysipelothrix rhusiopathiae?', '["Inhalation of spores", "Ingestion of contaminated milk", "Abrasion while handling fish or poultry", "Flea bite"]', 2, 'Erysipeloid is an occupational disease of butchers and fishermen.'),
    (v_topic_id, 'Which of the following is TRUE regarding the capsule of Bacillus anthracis?', '["It is composed of polysaccharide (PRP)", "It is composed of D-glutamate (polypeptide)", "It is absent in the virulent strain", "It is detected by the CAMP test"]', 1, 'Unique among bacteria, the B. anthracis capsule is proteinaceous (D-glutamate).');

    -- SECTION 3: GRAM-NEGATIVE COCCI & ENTERICS (31-45)
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A college student presents with high fever, neck stiffness, and a petechial rash. CSF shows Gram-negative diplococci. Which component of the organism is most responsible for the systemic inflammatory response and DIC?', '["Capsule", "Lipooligosaccharide (LOS)", "IgA protease", "Pili"]', 1, 'Neisseria meningitidis lacks O-antigen (LOS instead of LPS). The lipid A portion of LOS triggers massive TNF-alpha and IL-1 release.'),
    (v_topic_id, 'Which Neisseria species lacks a polysaccharide capsule and is primarily a cause of urethritis and pelvic inflammatory disease?', '["N. meningitidis", "N. gonorrhoeae", "N. sicca", "N. lactamica"]', 1, 'N. gonorrhoeae does not have a capsule; its primary virulence factors are pili (antigenic variation) and Opa proteins.'),
    (v_topic_id, 'A 3-year-old child with a high fever and headache is suspected of having bacterial meningitis. If the causative agent is Neisseria meningitidis, which of the following host deficiencies would most increase their risk?', '["C1-C4 complement deficiency", "C5-C9 complement deficiency", "B-cell deficiency", "NADPH oxidase deficiency"]', 1, 'Late complement component (MAC) deficiency predisposes patients to recurrent Neisseria infections.'),
    (v_topic_id, 'A traveler to Mexico develops profuse, watery diarrhea. The causative E. coli strain produces a heat-labile (LT) toxin. What is the mechanism of this toxin?', '["Activation of Guanylate cyclase", "ADP-ribosylation of Gs, activating Adenylate cyclase", "Inhibition of 60S ribosome", "Cleavage of rRNA"]', 1, 'ETEC heat-labile toxin (LT) increases cAMP (like Cholera toxin). Heat-stable toxin (ST) increases cGMP.'),
    (v_topic_id, 'A child develops bloody diarrhea and later presents with oliguria, anemia, and thrombocytopenia (HUS). The organism is a Gram-negative rod that does NOT ferment sorbitol. What is the toxin mechanism?', '["Increases cAMP", "Cleaves the 28S rRNA of the 60S ribosomal subunit", "Activates Gs proteins", "Forms pores in the cell membrane"]', 1, 'EHEC (O157:H7) produces Shiga-like toxin (Verotoxin), which inhibits protein synthesis by targeting the 60S ribosome.'),
    (v_topic_id, 'What is the most common cause of neonatal meningitis? (Hint: The organism is a Gram-negative rod with a K1 capsular antigen)', '["Streptococcus agalactiae", "Escherichia coli", "Listeria monocytogenes", "Haemophilus influenzae"]', 1, 'While GBS is #1, E. coli with K1 capsule is the #2 cause of neonatal meningitis.'),
    (v_topic_id, 'Which organism is a motile, Gram-negative rod that produces H2S (black colonies on Hektoen agar) and is a common cause of osteomyelitis in Sickle Cell patients?', '["Shigella sonnei", "Salmonella enteritidis", "Proteus mirabilis", "Klebsiella pneumoniae"]', 1, 'Salmonella species are H2S positive and motile, unlike Shigella.'),
    (v_topic_id, 'A patient presents with a step-ladder fever, "rose spots" on the abdomen, and abdominal pain. Blood cultures grow a Gram-negative rod. The organism survives within macrophages. This is:', '["Salmonella typhi", "Shigella dysenteriae", "Vibrio cholerae", "Yersinia enterocolitica"]', 0, 'Typhoid fever is characterized by the Vi capsule, rose spots, and a carrier state in the gallbladder.'),
    (v_topic_id, 'Which organism causes "rice-water" stools and is characterized by a "comma-shaped" Gram-negative rod that is oxidase-positive?', '["Campylobacter jejuni", "Vibrio cholerae", "Helicobacter pylori", "Pseudomonas aeruginosa"]', 1, 'Vibrio cholerae produces a massive watery diarrhea via a toxin that permanently activates Gs.'),
    (v_topic_id, 'A child presents with right lower quadrant pain mimicking appendicitis and bloody diarrhea. He recently played with a new pet puppy. The organism is:', '["E. coli (EHEC)", "Yersinia enterocolitica", "Salmonella typhi", "Shigella flexneri"]', 1, 'Yersinia enterocolitica causes pseudoappendicitis due to mesenteric adenitis and is often transmitted via puppies or contaminated milk.'),
    (v_topic_id, 'A patient with a UTI has alkaline urine (pH > 8). The causative organism is a Gram-negative rod that shows "swarming" motility on agar. What enzyme is responsible?', '["Catalase", "Urease", "Oxidase", "Lecithinase"]', 1, 'Proteus mirabilis produces urease, which converts urea to ammonia, raising the urine pH and predisposing to struvite stones.'),
    (v_topic_id, 'A patient with chronic gastritis and peptic ulcers is diagnosed with Helicobacter pylori. What is the primary role of its urease enzyme in pathogenesis?', '["Directly damages the gastric mucosa", "Neutralizes stomach acid to allow survival", "Inhibits gastrin release", "Promotes mucus production"]', 1, 'Urease creates an alkaline microenvironment (ammonia) around the bacteria, protecting it from gastric acid.'),
    (v_topic_id, 'Which Gram-negative enteric is a major cause of pneumonia in alcoholics and diabetics, characterized by "currant jelly" sputum?', '["Pseudomonas aeruginosa", "Klebsiella pneumoniae", "Serratia marcescens", "Enterobacter cloacae"]', 1, 'Klebsiella has a very thick mucoid capsule, leading to the characteristic thick sputum.'),
    (v_topic_id, 'What is the most common cause of traveler''s diarrhea?', '["ETEC", "EHEC", "EIEC", "EPEC"]', 0, 'Enterotoxigenic E. coli (ETEC) is the classic "Montezuma''s Revenge."'),
    (v_topic_id, 'Shigella species are highly infectious (low ID50) because they:', '["Produce a very potent exotoxin", "Are resistant to stomach acid", "Are motile and spread quickly", "Can form spores"]', 1, 'Unlike Salmonella, Shigella is acid-stable and requires very few organisms (10-100) to cause disease.');

    -- SECTION 4: RESPIRATORY & ZOONOTIC GRAM-NEGATIVES (46-60)
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 2-year-old child with high fever and a "cherry-red" epiglottis is in respiratory distress. He is not vaccinated. What is the primary virulence factor of the likely organism?', '["Lipopolysaccharide", "Polyribosylribitol phosphate (PRP) capsule", "IgA protease", "Exotoxin A"]', 1, 'Haemophilus influenzae type b (Hib) uses its PRP capsule to cause invasive disease like epiglottitis and meningitis.'),
    (v_topic_id, 'Which growth requirements are essential for Haemophilus influenzae on chocolate agar?', '["Factors V (NAD+) and X (Hematin)", "Cysteine and Iron", "Glucose and Salts", "Low CO2 and High Oxygen"]', 0, 'Chocolate agar provides both X and V factors released from lysed RBCs.'),
    (v_topic_id, 'A 65-year-old smoker presents with "atypical" pneumonia, diarrhea, and confusion. Labs show hyponatremia. Gram stain of sputum shows many neutrophils but no organisms. It grows on Buffered Charcoal Yeast Extract (BCYE) agar. Organism?', '["Mycoplasma pneumoniae", "Legionella pneumophila", "Chlamydophila pneumoniae", "Coxiella burnetii"]', 1, 'Legionella is a facultative intracellular rod that stains poorly and is associated with water sources (AC units).'),
    (v_topic_id, 'What is the mechanism of the Pertussis toxin?', '["Activates Gs", "Inhibits Gi by ADP-ribosylation, increasing cAMP", "Cleaves MAPKK", "Inhibits EF-2"]', 1, 'Pertussis toxin inhibits the inhibitory G-protein (Gi), leading to overactive adenylate cyclase and high cAMP levels, which impairs leukocyte chemotaxis.'),
    (v_topic_id, 'A patient with Cystic Fibrosis has a chronic cough producing blue-green sputum with a "fruity" odor. The organism is an oxidase-positive, non-lactose fermenting Gram-negative rod. What is its mechanism of Exotoxin A?', '["Activation of adenylate cyclase", "Inactivation of EF-2", "Inhibition of 60S ribosome", "Cleavage of SNARE proteins"]', 1, 'Pseudomonas aeruginosa Exotoxin A has the same mechanism as Diphtheria toxin (EF-2 inactivation).'),
    (v_topic_id, 'Which of the following is a common complication of Campylobacter jejuni infection, characterized by ascending paralysis due to molecular mimicry?', '["Reactive arthritis", "Guillain-Barre Syndrome", "Hemolytic Uremic Syndrome", "Rheumatic Fever"]', 1, 'Campylobacter is the #1 trigger for GBS.'),
    (v_topic_id, 'A hunter develops a fever and a painful lymph node (bubo) after skinning a rabbit. The organism is a pleomorphic Gram-negative coccobacillus. Diagnosis?', '["Pasteurella multocida", "Francisella tularensis", "Yersinia pestis", "Brucella melitensis"]', 1, 'Tularemia is often transmitted via rabbits, ticks, or deer flies.'),
    (v_topic_id, 'A patient is bitten by a cat and develops a rapidly progressing cellulitis within 24 hours. The organism is a Gram-negative coccobacillus with a "mousy" odor. It is:', '["Bartonella henselae", "Pasteurella multocida", "Capnocytophaga canimorsus", "Eikenella corrodens"]', 1, 'Pasteurella is found in the mouths of cats/dogs; Bartonella causes "Cat Scratch Disease" (lymphadenopathy, not rapid cellulitis).'),
    (v_topic_id, 'A farmer presents with a "undulating" fever (rising in the day, falling at night), sweats, and joint pain. He frequently consumes unpasteurized goat milk. Diagnosis?', '["Listeriosis", "Brucellosis", "Q Fever", "Anthrax"]', 1, 'Brucella causes undulant fever and is associated with unpasteurized dairy and infected livestock.'),
    (v_topic_id, 'What is the vector for Yersinia pestis (the Plague)?', '["Ixodes tick", "Xenopsylla cheopis (Flea)", "Anopheles mosquito", "Body louse"]', 1, 'Fleas transmit the plague from rodents to humans.'),
    (v_topic_id, 'A patient presents with a painless, beefy red genital ulcer that bleeds easily on contact. Biopsy shows "Donovan bodies" (intracellular organisms in macrophages). Diagnosis?', '["Syphilis", "Granuloma inguinale (Klebsiella granulomatis)", "Chancroid", "Lymphogranuloma venereum"]', 1, 'Klebsiella granulomatis causes granuloma inguinale (Donovanosis).'),
    (v_topic_id, 'Which organism causes a painful genital ulcer (chancroid) and appears as a "school of fish" on Gram stain?', '["Treponema pallidum", "Haemophilus ducreyi", "Chlamydia trachomatis", "HSV-2"]', 1, 'H. ducreyi (You "do cry" because it''s painful). Syphilis is painless.'),
    (v_topic_id, 'A 15-year-old girl with Cystic Fibrosis has a pulmonary infection with Burkholderia cepacia. This is particularly concerning because:', '["It is highly resistant to most antibiotics", "It causes rapid decline in lung function (Cepacia syndrome)", "It is transmitted via mosquitoes", "It produces a potent neurotoxin"]', 1, 'B. cepacia is a feared pathogen in CF patients due to its high resistance and poor prognosis.'),
    (v_topic_id, 'Which organism is the most common cause of "Cat Scratch Disease"?', '["Pasteurella multocida", "Bartonella henselae", "Afipia felis", "Toxoplasma gondii"]', 1, 'Bartonella causes regional lymphadenopathy after a cat scratch or bite.'),
    (v_topic_id, 'A man develops a severe headache and fever after exploring a cave inhabited by bats. If the cause is a bacterium found in the stool of birds and bats, what is it?', '["Histoplasma capsulatum", "Leptospira interrogans", "Pseudomonas aeruginosa", "None of the above (it is fungal)"]', 3, 'Histoplasma is a fungus found in bat/bird droppings. No major bacterial pathogen fits this specific "cave/bat" classic vignette better than the fungus.');

    -- SECTION 5: MYCOBACTERIA & ACTINOMYCETES (61-70)
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'Which component of the Mycobacterium tuberculosis cell wall is responsible for its "acid-fast" staining property?', '["Peptidoglycan", "Mycolic acids", "Lipoarabinomannan", "Cord factor"]', 1, 'Mycolic acids are long-chain fatty acids that prevent the uptake of Gram stain but retain carbolfuchsin.'),
    (v_topic_id, 'What is the function of the "Cord Factor" in Mycobacterium tuberculosis?', '["Inhibits phagosome-lysosome fusion", "Inhibits macrophage maturation and induces TNF-alpha", "Degrades host DNA", "Forms pores in the cell membrane"]', 1, 'Cord factor (Trehalose dimycolate) is a virulence factor that inhibits leukocyte migration and causes granuloma formation.'),
    (v_topic_id, 'A patient with AIDS has a CD4 count of 40 and presents with fever, weight loss, and anemia. Blood cultures are positive for acid-fast bacilli. What is the most likely organism?', '["M. tuberculosis", "M. avium-intracellulare complex (MAC)", "M. leprae", "M. marinum"]', 1, 'MAC causes disseminated disease in advanced AIDS (CD4 < 50). Prophylaxis with Azithromycin is indicated.'),
    (v_topic_id, 'A patient from Southeast Asia presents with hypopigmented skin patches on his arms that are anesthetic (lack sensation). He has thickened ulnar nerves. He has a strong Th1 response and positive lepromin skin test. Which form of leprosy is this?', '["Tuberculoid", "Lepromatous", "Borderline", "Histoid"]', 0, 'Tuberculoid leprosy is the mild form with a strong cell-mediated (Th1) response that limits the infection to a few lesions.'),
    (v_topic_id, 'In the lepromatous form of leprosy, the patient has a weak Th1 response and a predominant Th2 response. This leads to:', '["High bacterial load and \"lion-like\" facies", "Spontaneous resolution", "Single anesthetic patch", "Acute pneumonia"]', 0, 'Lepromatous leprosy (Th2 response) is characterized by diffuse skin involvement, high bacterial load, and communicability.'),
    (v_topic_id, 'What is the drug of choice for treating Nocardia infections?', '["Penicillin", "Trimethoprim-Sulfamethoxazole (TMP-SMX)", "Clindamycin", "Amphotericin B"]', 1, 'SNAP: Sulfa for Nocardia, Actinomyces gets Penicillin.'),
    (v_topic_id, 'A 40-year-old male presents with chronic cough, night sweats, and weight loss. CXR shows a cavitary lesion in the right upper lobe. What is the primary mediator of the caseous necrosis seen in his granulomas?', '["Direct bacterial toxin", "TNF-alpha and IFN-gamma from T-cells/Macrophages", "Neutrophil degranulation", "Antibody-dependent cellular cytotoxicity"]', 1, 'The tissue damage in TB is host-mediated (Type IV hypersensitivity).'),
    (v_topic_id, 'Which Mycobacterium species causes a "fish tank granuloma" after a skin abrasion in a swimming pool or aquarium?', '["M. kansasii", "M. marinum", "M. scrofulaceum", "M. ulcerans"]', 1, 'M. marinum causes localized skin infections in people handling fish or cleaning tanks.'),
    (v_topic_id, 'A child presents with a painless, swollen lymph node in the neck (scrofula) without systemic symptoms. The most common non-tuberculous mycobacterium responsible is:', '["M. avium", "M. scrofulaceum", "M. tuberculosis", "M. leprae"]', 1, 'M. scrofulaceum is a classic cause of cervical lymphadenitis in children.'),
    (v_topic_id, 'What is the mechanism of action of Isoniazid (INH)?', '["Inhibits DNA-dependent RNA polymerase", "Inhibits mycolic acid synthesis", "Inhibits arabinosyltransferase", "Inhibits ATP synthase"]', 1, 'INH inhibits mycolic acid synthesis. Rifampin inhibits RNA polymerase. Ethambutol inhibits arabinosyltransferase.');

    RAISE NOTICE 'SUCCESS: Systemic Microbiology MCQ Part 1 (1-70) registered.';
END $$;

COMMIT;
